inline int64_t GetDim(const gert::Shape* s, int idx) {
    return s->GetStorageShape()[idx];
}
}

namespace optiling {

const uint32_t BLOCK_DIM = 1; // 为了简化Device实现，这里使用单block计算

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvT3dAsymStridedPaddedGroupedTiling tiling;

    // 输入
    const gert::Shape* xShape = context->GetInputShape(0); // x: [N, Cin, Din, Hin, Win]
    const gert::Shape* wShape = context->GetInputShape(1); // weight: [Cin, CoutPerGroup, Kd, Kh, Kw]

    int64_t N   = GetDim(xShape, 0);
    int64_t Cin = GetDim(xShape, 1);
    int64_t Din = GetDim(xShape, 2);
    int64_t Hin = GetDim(xShape, 3);
    int64_t Win = GetDim(xShape, 4);

    int64_t W_Cin  = GetDim(wShape, 0);
    int64_t W_Cpg  = GetDim(wShape, 1);
    int64_t Kd     = GetDim(wShape, 2);
    int64_t Kh     = GetDim(wShape, 3);
    int64_t Kw     = GetDim(wShape, 4);

    // 读取属性：stride/padding/output_padding/groups
    // 期望Python端以IntList(3)和Int(1)方式传入
    std::vector<int64_t> stride = context->GetAttr("stride")->GetIntList();
    std::vector<int64_t> padding = context->GetAttr("padding")->GetIntList();
    std::vector<int64_t> out_pad = context->GetAttr("output_padding")->GetIntList();
    int64_t groups = context->GetAttr("groups")->GetInt();

    int64_t sd = stride.size() > 0 ? stride[0] : 1;
    int64_t sh = stride.size() > 1 ? stride[1] : 1;
    int64_t sw = stride.size() > 2 ? stride[2] : 1;

    int64_t pd = padding.size() > 0 ? padding[0] : 0;
    int64_t ph = padding.size() > 1 ? padding[1] : 0;
    int64_t pw = padding.size() > 2 ? padding[2] : 0;

    int64_t opd = out_pad.size() > 0 ? out_pad[0] : 0;
    int64_t oph = out_pad.size() > 1 ? out_pad[1] : 0;
    int64_t opw = out_pad.size() > 2 ? out_pad[2] : 0;

    int64_t Cout = W_Cpg * groups;

    // 输出形状
    int64_t Dout = (Din - 1) * sd - 2 * pd + Kd + opd;
    int64_t Hout = (Hin - 1) * sh - 2 * ph + Kh + oph;
    int64_t Wout = (Win - 1) * sw - 2 * pw + Kw + opw;

    context->SetBlockDim(BLOCK_DIM);

    // 设置tiling
    tiling.set_n((uint32_t)N);
    tiling.set_cin((uint32_t)Cin);
    tiling.set_cout((uint32_t)Cout);
    tiling.set_din((uint32_t)Din);
    tiling.set_hin((uint32_t)Hin);
    tiling.set_win((uint32_t)Win);
    tiling.set_kd((uint32_t)Kd);
    tiling.set_kh((uint32_t)Kh);
    tiling.set_kw((uint32_t)Kw);

    tiling.set_sd((uint32_t)sd);
    tiling.set_sh((uint32_t)sh);
    tiling.set_sw((uint32_t)sw);
    tiling.set_pd((uint32_t)pd);
    tiling.set_ph((uint32_t)ph);
    tiling.set_pw((uint32_t)pw);
    tiling.set_opd((uint32_t)opd);
    tiling.set_oph((uint32_t)oph);
    tiling.set_opw((uint32_t)opw);

    tiling.set_groups((uint32_t)groups);

    bool hasBias = (context->GetNumInputs() > 2) && (context->GetInputShape(2) != nullptr);
    tiling.set_hasBias(hasBias ? 1u : 0u);

    uint64_t xSize = (uint64_t)N * Cin * Din * Hin * Win;
    uint64_t wSize = (uint64_t)Cin * W_Cpg * Kd * Kh * Kw;
    uint64_t bSize = (uint64_t)Cout;
    uint64_t ySize = (uint64_t)N * Cout * Dout * Hout * Wout;

    tiling.set_xSize(xSize);
    tiling.set_wSize(wSize);
    tiling.set_bSize(bSize);
    tiling.set_ySize(ySize);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    workspaceSizes[0] = 0; // 无需额外workspace

    return ge::GRAPH_SUCCESS;
}

