python_bind_src="""
#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

static inline std::array<int64_t, 3> get_tuple3(const c10::optional<at::IntArrayRef>& v, int64_t d=1, int64_t h=1, int64_t w=1) {
    if (v.has_value() && v->size() == 3) {
        return {(*v)[0], (*v)[1], (*v)[2]};
    }
    return {d, h, w};
}

at::Tensor conv_transposed_3d_asymmetric_input_asymmetric_kernel_strided_padded_grouped_custom_impl_npu(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias_opt,
    at::IntArrayRef stride,
    at::IntArrayRef padding,
    at::IntArrayRef output_padding,
    int64_t groups)
{
    TORCH_CHECK(x.dim() == 5, "x must be 5D [N,C,D,H,W]");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D [Cin, CoutPerG, Kd, Kh, Kw]");
    TORCH_CHECK(stride.size() == 3 && padding.size() == 3 && output_padding.size() == 3, "stride/padding/output_padding must be 3D");

    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t Din = x.size(2);
    int64_t Hin = x.size(3);
    int64_t Win = x.size(4);

    int64_t W_Cpg = weight.size(1);
    int64_t Kd = weight.size(2);
    int64_t Kh = weight.size(3);
    int64_t Kw = weight.size(4);

    int64_t sd = stride[0], sh = stride[1], sw = stride[2];
    int64_t pd = padding[0], ph = padding[1], pw = padding[2];
    int64_t opd = output_padding[0], oph = output_padding[1], opw = output_padding[2];

    int64_t Cout = W_Cpg * groups;
    int64_t Dout = (Din - 1) * sd - 2 * pd + Kd + opd;
    int64_t Hout = (Hin - 1) * sh - 2 * ph + Kh + oph;
    int64_t Wout = (Win - 1) * sw - 2 * pw + Kw + opw;

    at::Tensor y = at::empty({N, Cout, Dout, Hout, Wout}, x.options());

    if (bias_opt.has_value()) {
        EXEC_NPU_CMD(aclnnConvTransposed3dAsymmetricInputAsymmetricKernelStridedPaddedGroupedCustom,
                     x, weight, bias_opt.value(), y,
                     (int64_t)sd, (int64_t)sh, (int64_t)sw,
                     (int64_t)pd, (int64_t)ph, (int64_t)pw,
                     (int64_t)opd, (int64_t)oph, (int64_t)opw,
                     (int64_t)groups);
    } else {
        // 传入一个空Tensor代表无bias
        at::Tensor empty_bias;
